import json, subprocess, urllib.parse

def api(method, *fields):
    data = [('token', '<TOKEN>')]
    for f in fields:
        data.append(f)
    body = urllib.parse.urlencode(data).encode()
    r = subprocess.run(['curl', '-s', '-X', 'POST', f'https://slack.com/api/{method}',
                        '--data', body.decode()], capture_output=True, text=True)
    return json.loads(r.stdout)

# Deebo's (U_FARHAN) candidate messages
for ts in ['1772378100.000004', '1772377200.000001']:
    r = api('reactions.get', ('channel', 'C_LAUNCH'), ('timestamp', ts))
    print(ts, '->', json.dumps(r))
    t = api('conversations.replies', ('channel', 'C_LAUNCH'), ('ts', ts))
    for m in t.get('messages', []):
        print('   thread:', m['ts'], m['user'], json.dumps(m.get('reactions', [])), (m.get('text') or '')[:80])

# Also scan every message in the channel for eyes reactions, including any thread roots
h = api('conversations.history', ('channel', 'C_LAUNCH'), ('limit', '500'))
for m in h.get('messages', []):
    if m.get('reactions'):
        print('HAS REACTIONS:', m['ts'], m['user'], json.dumps(m.get('reactions')))

